/*
 * Generated by the /ship test coverage audit.
 *
 * Value: protects=publishing never uses another org's connection, republishes in place only on the same
 *   connection, and a URL change never carries the stored token; fails_when=the org check, the
 *   existingPageId guard or the token-host guard is removed or inverted; why_new=confluence.client.spec.ts
 *   and storage-format.spec.ts cover the HTTP client and converter only, nothing covers ConfluenceService;
 *   seam=none; no_claim=real Confluence and perfana-report (client functions and renderer are mocked; unit only)
 */
import { BadRequestException, ConflictException, ForbiddenException, NotFoundException } from '@nestjs/common';
import { ConfluenceService } from './confluence.service';
import { ConfluenceError, confluenceSpace, ensurePagePath, upsertPage, uploadAttachments } from './confluence.client';
import { chartFilename } from './storage-format';

jest.mock('./confluence.client', () => {
  const actual = jest.requireActual('./confluence.client');
  return { ...actual, upsertPage: jest.fn(), uploadAttachments: jest.fn(), confluenceSpace: jest.fn(), ensurePagePath: jest.fn() };
});

const mockedUpsert = upsertPage as jest.MockedFunction<typeof upsertPage>;
const mockedUpload = uploadAttachments as jest.MockedFunction<typeof uploadAttachments>;
const mockedSpace = confluenceSpace as jest.MockedFunction<typeof confluenceSpace>;
const mockedEnsurePath = ensurePagePath as jest.MockedFunction<typeof ensurePagePath>;

const ORG_A = '00000000-0000-0000-0000-00000000000a';
const ORG_B = '00000000-0000-0000-0000-00000000000b';
const CFG = '22222222-2222-2222-2222-222222222222';
const OTHER_CFG = '33333333-3333-3333-3333-333333333333';
const REPORT = '44444444-4444-4444-4444-444444444444';

const storedConfig = (over: Record<string, unknown> = {}) => ({
  id: CFG,
  label: 'wiki',
  deployment: 'cloud',
  baseUrl: 'https://example.atlassian.net',
  username: 'user@example.com',
  apiToken: 'stored-token',
  spaceKey: 'SPACE',
  parentPageId: null,
  useProxy: false,
  organizationId: ORG_A,
  ...over,
});

function build(opts: { caps?: string[]; sutParentPages?: Record<string, string> } = {}) {
  const configRepo = {
    create: jest.fn((x) => x),
    save: jest.fn(async (x) => ({ id: CFG, ...x })),
    findOne: jest.fn(async () => storedConfig()),
    delete: jest.fn(),
    target: 'ConfluenceConfig',
  };
  const reportRepo = { update: jest.fn(), target: 'GeneratedReport' };
  const sutRepo = {
    findOne: jest.fn(async () => ({ id: 'sut-1', confluence_parent_pages: opts.sutParentPages ?? {} })),
    target: 'SystemUnderTest',
  };
  const authz = {
    getAccessibleOrganizations: jest.fn(async () => [ORG_A]),
    isGlobalAdmin: jest.fn(() => false),
    getCapabilities: jest.fn(async () => opts.caps ?? [
      'integration:confluence:create', 'integration:confluence:update', 'integration:confluence:delete',
    ]),
    canAccessResource: jest.fn(async () => ({ allowed: true })),
  };
  const audit = { logCreate: jest.fn(), logUpdate: jest.fn(), logDelete: jest.fn() };
  const proxy = { resolve: jest.fn(async () => null) };
  const reports = {
    assertCanChangeSharing: jest.fn(async () => undefined),
    findById: jest.fn(async () => ({
      id: REPORT,
      name: 'Load test report',
      html_content: '<html></html>',
      test_run_id: 'run-uuid',
      test_run: { testRunId: 'SYSTEM-env-load-0001', organizationId: ORG_A, systemUnderTestId: 'sut-1' },
      confluence_config_id: CFG,
      confluence_page_id: '9001',
    })),
  };
  const renderer = {
    render: jest.fn(async () => ({
      html: '<html><body><p>Summary</p><img data-confluence-chart="0" width="800"><img data-confluence-chart="0" width="800"><img data-confluence-chart="5" width="800"></body></html>',
      images: [Buffer.from('png').toString('base64')],
    })),
  };
  const service = new ConfluenceService(
    configRepo as never, reportRepo as never, sutRepo as never, authz as never, audit as never,
    proxy as never, reports as never, renderer as never,
  );
  return { service, configRepo, reportRepo, sutRepo, authz, reports, renderer };
}

/** The parent upsertPage would create the page under (it calls the resolver only on create). */
const resolvedParent = () => mockedUpsert.mock.calls[0]![1].resolveParentPageId!();

beforeEach(() => {
  mockedUpsert.mockReset().mockResolvedValue({ id: '9001', url: 'https://example.atlassian.net/wiki/spaces/SPACE/pages/9001' });
  mockedUpload.mockReset().mockResolvedValue(undefined);
  mockedEnsurePath.mockReset().mockResolvedValue('5555');
});

describe('ConfluenceService.publishReport', () => {
  it("publishes under the system's page path for this connection, resolved below the connection's parent page", async () => {
    const { service, configRepo } = build({ sutParentPages: { [CFG]: 'Performance / MyApp', [OTHER_CFG]: 'Elsewhere' } });
    configRepo.findOne.mockResolvedValue(storedConfig({ parentPageId: '77' }));

    await service.publishReport(REPORT, { configId: CFG }, 'u', [], 'https://perfana.example.com');

    // The walk is deferred to upsertPage, which runs it only when it creates a page.
    expect(mockedEnsurePath).not.toHaveBeenCalled();
    expect(await resolvedParent()).toBe('5555');
    expect(mockedEnsurePath).toHaveBeenCalledWith(expect.anything(), 'SPACE', '77', ['Performance', 'MyApp'], expect.anything());
  });

  it("falls back to the connection's parent page when the system sets no path for this connection", async () => {
    const { service, configRepo } = build({ sutParentPages: { [OTHER_CFG]: 'Elsewhere' } });
    configRepo.findOne.mockResolvedValue(storedConfig({ parentPageId: '77' }));

    await service.publishReport(REPORT, { configId: CFG }, 'u', [], 'https://perfana.example.com');

    expect(await resolvedParent()).toBe('77');
    expect(mockedEnsurePath).not.toHaveBeenCalled();
  });

  /*
   * Generated by the /ship test coverage audit (pass 1).
   * Value: protects=a run with no systemUnderTestId still publishes, under the connection's parent page, without a system lookup;
   *   fails_when=parentPageFor queries the system with an undefined id (TypeORM matches any row) or throws on the missing relation;
   *   why_new=both parent-page tests set systemUnderTestId; seam=none; no_claim=real repository semantics (mocked repo; unit only)
   */
  it('publishes under the connection parent without a system lookup when the run carries no system id', async () => {
    const { service, configRepo, sutRepo, reports } = build({ sutParentPages: { [CFG]: 'Performance / MyApp' } });
    configRepo.findOne.mockResolvedValue(storedConfig({ parentPageId: '77' }));
    const base = await reports.findById();
    reports.findById.mockResolvedValueOnce({ ...base, test_run: { ...base.test_run, systemUnderTestId: undefined } } as never);

    await service.publishReport(REPORT, { configId: CFG }, 'u', [], 'https://perfana.example.com');

    expect(await resolvedParent()).toBe('77');
    expect(sutRepo.findOne).not.toHaveBeenCalled();
    expect(mockedEnsurePath).not.toHaveBeenCalled();
  });

  it("refuses a connection that belongs to another organization than the report's run, before rendering or calling Confluence", async () => {
    const { service, configRepo, renderer, reportRepo } = build();
    configRepo.findOne.mockResolvedValue(storedConfig({ organizationId: ORG_B }));

    await expect(service.publishReport(REPORT, { configId: CFG }, 'u', [], 'https://perfana.example.com'))
      .rejects.toBeInstanceOf(BadRequestException);
    expect(renderer.render).not.toHaveBeenCalled();
    expect(mockedUpsert).not.toHaveBeenCalled();
    expect(reportRepo.update).not.toHaveBeenCalled();
  });

  it('updates the earlier page only on the same connection, attaches each rendered chart once, and records the page', async () => {
    const { service, reportRepo } = build();

    const out = await service.publishReport(REPORT, { configId: CFG }, 'u', [], 'https://perfana.example.com');

    const [, input] = mockedUpsert.mock.calls[0]!;
    expect(input.existingPageId).toBe('9001');
    expect(input.title).toBe('Load test report (SYSTEM-env-load-0001)');
    expect(input.storage).toContain('https://perfana.example.com/test-runs/SYSTEM-env-load-0001');
    // chart 0 is referenced twice, chart 5 has no image: one attachment.
    const files = mockedUpload.mock.calls[0]![2];
    expect(files.map((f) => f.filename)).toEqual([chartFilename(0)]);
    expect(out.charts).toBe(1);
    expect(reportRepo.update).toHaveBeenCalledWith(REPORT, expect.objectContaining({
      confluence_config_id: CFG, confluence_page_id: '9001',
    }));

    // A different connection of the same org must create a fresh page, never touch the old one.
    const second = build();
    second.configRepo.findOne.mockResolvedValue(storedConfig({ id: OTHER_CFG }));
    await second.service.publishReport(REPORT, { configId: OTHER_CFG }, 'u', [], 'https://perfana.example.com');
    expect(mockedUpsert.mock.calls[1]![1].existingPageId).toBeNull();
  });

  it("turns Confluence's refusal into a 400 carrying its reason and records nothing", async () => {
    const { service, reportRepo } = build();
    mockedUpsert.mockRejectedValue(new ConfluenceError('A page with this title already exists', 400));

    const publish = service.publishReport(REPORT, { configId: CFG }, 'u', [], 'https://perfana.example.com');
    await expect(publish).rejects.toBeInstanceOf(BadRequestException);
    await expect(publish).rejects.toThrow('Confluence: A page with this title already exists');
    expect(reportRepo.update).not.toHaveBeenCalled();
  });

  /*
   * Generated by the /ship test coverage audit (pass 2).
   * Value: protects=a failed page-path walk maps to a 400 with Confluence's reason, creates no report page and records nothing;
   *   fails_when=parentPageFor moves outside the try (raw ConfluenceError -> 500) or the upsert still runs after the walk fails;
   *   why_new=every publish test lets ensurePagePath resolve; seam=none; no_claim=real Confluence (client functions mocked; unit only)
   */
  it('turns a refused page-path walk into a 400 and neither creates the report page nor records it', async () => {
    const { service, configRepo, reportRepo } = build({ sutParentPages: { [CFG]: 'Performance / MyApp' } });
    configRepo.findOne.mockResolvedValue(storedConfig({ parentPageId: '77' }));
    mockedEnsurePath.mockRejectedValue(new ConfluenceError('The parent page does not exist', 404));
    // As upsertPage does when it creates a page: resolve the parent first.
    mockedUpsert.mockImplementation(async (_c, input) => {
      await input.resolveParentPageId!();
      return { id: '9001', url: 'u' };
    });

    const publish = service.publishReport(REPORT, { configId: CFG }, 'u', [], 'https://perfana.example.com');
    await expect(publish).rejects.toBeInstanceOf(BadRequestException);
    await expect(publish).rejects.toThrow('The parent page does not exist');
    expect(mockedUpload).not.toHaveBeenCalled();
    expect(reportRepo.update).not.toHaveBeenCalled();
  });

  /*
   * Value: protects=a page created before a failed chart upload is remembered, so the retry updates it
   *   instead of POSTing a same-title page Confluence refuses; fails_when=the page is recorded only after
   *   the upload again; why_new=no case covered a failed upload; seam=none; no_claim=real Confluence
   *   (client functions mocked; unit only)
   */
  it('remembers the created page when the chart upload fails, without marking it published', async () => {
    const { service, reportRepo } = build();
    mockedUpload.mockRejectedValue(new ConfluenceError('Request entity too large', 413));

    await expect(service.publishReport(REPORT, { configId: CFG }, 'u', [], 'https://perfana.example.com'))
      .rejects.toBeInstanceOf(BadRequestException);
    expect(reportRepo.update).toHaveBeenCalledWith(REPORT, expect.objectContaining({ confluence_config_id: CFG, confluence_page_id: '9001' }));
    expect(reportRepo.update).not.toHaveBeenCalledWith(REPORT, expect.objectContaining({ confluence_published_at: expect.anything() }));
  });
});

describe('ConfluenceService guards (pass 2)', () => {
  /*
   * Generated by the /ship test coverage audit (pass 2).
   * Value: protects=another tenant's connection is a 404 by id and a user with no orgs lists nothing;
   *   fails_when=loadConfig's access check or listConfigs' empty-org early return is removed;
   *   why_new=pass-1 cases mock access as always allowed; seam=none; no_claim=RLS (mocked authz; unit only)
   */
  it('hides a connection the caller cannot access as 404, and lists nothing for a user with no organization', async () => {
    const { service, authz, configRepo } = build();
    authz.canAccessResource.mockResolvedValue({ allowed: false });
    await expect(service.getConfig(CFG, 'u', [])).rejects.toBeInstanceOf(NotFoundException);
    await expect(service.deleteConfig(CFG, 'u', [])).rejects.toBeInstanceOf(NotFoundException);
    expect(configRepo.delete).not.toHaveBeenCalled();

    authz.getAccessibleOrganizations.mockResolvedValue([]);
    (configRepo as unknown as { createQueryBuilder: jest.Mock }).createQueryBuilder = jest.fn();
    await expect(service.listConfigs('u', [])).resolves.toEqual([]);
    expect((configRepo as unknown as { createQueryBuilder: jest.Mock }).createQueryBuilder).not.toHaveBeenCalled();
  });

  /*
   * Value: protects=a report without HTML is refused with 409 before rendering, and a failed connection test
   *   answers {success:false} rather than a 500; fails_when=the html guard or probe's catch is removed;
   *   why_new=uncovered; seam=none; no_claim=real Confluence (client mocked; unit only)
   */
  it('refuses to publish a report with no HTML yet, and reports a failed connection test without throwing', async () => {
    const { service, reports, renderer } = build();
    reports.findById.mockResolvedValue({ ...(await reports.findById()), html_content: null } as never);
    await expect(service.publishReport(REPORT, { configId: CFG }, 'u', [], 'https://perfana.example.com'))
      .rejects.toBeInstanceOf(ConflictException);
    expect(renderer.render).not.toHaveBeenCalled();

    mockedSpace.mockResolvedValueOnce({ id: '1', name: 'Perf Space' });
    await expect(service.testSavedConnection(CFG, 'u', [])).resolves.toEqual({
      success: true, message: expect.stringContaining('"Perf Space"'),
    });
    mockedSpace.mockRejectedValueOnce(new ConfluenceError('Confluence rejected the credentials (401)', 401));
    await expect(service.testSavedConnection(CFG, 'u', [])).resolves.toEqual({
      success: false, message: 'Confluence rejected the credentials (401)',
    });
  });
});

describe('ConfluenceService connections', () => {
  it('never sends the stored token to a new URL, keeps it when the mask is echoed back, and masks every response', async () => {
    const { service, configRepo } = build();

    await expect(service.updateConfig(CFG, { baseUrl: 'https://other.example.net' }, 'u', []))
      .rejects.toThrow('needs the token entered again');
    await expect(service.updateConfig(CFG, { baseUrl: 'https://other.example.net', apiToken: '[MASKED]' }, 'u', []))
      .rejects.toThrow('needs the token entered again');
    expect(configRepo.save).not.toHaveBeenCalled();

    const kept = await service.updateConfig(CFG, { apiToken: '[MASKED]', label: 'renamed' }, 'u', []);
    expect(configRepo.save).toHaveBeenLastCalledWith(expect.objectContaining({ apiToken: 'stored-token', label: 'renamed' }));
    expect(kept.apiToken).toBe('[MASKED]');

    await service.updateConfig(CFG, { baseUrl: 'https://other.example.net/', apiToken: 'fresh' }, 'u', []);
    expect(configRepo.save).toHaveBeenLastCalledWith(expect.objectContaining({ baseUrl: 'https://other.example.net', apiToken: 'fresh' }));
  });

  it('checks the capability in the organization the body names, and requires the account email for Cloud', async () => {
    const denied = build({ caps: [] });
    const dto = { label: 'w', deployment: 'cloud' as const, baseUrl: 'https://example.atlassian.net/wiki/', username: 'user@example.com', apiToken: 't', spaceKey: 'SPACE' };
    await expect(denied.service.createConfig({ ...dto, organizationId: ORG_B }, 'u', [])).rejects.toBeInstanceOf(ForbiddenException);
    expect(denied.authz.getCapabilities).toHaveBeenCalledWith('u', [], ORG_B);

    const { service, configRepo } = build();
    await expect(service.createConfig({ ...dto, username: '  ' }, 'u', [])).rejects.toThrow('Atlassian account email');
    const created = await service.createConfig(dto, 'u', []);
    expect(configRepo.save).toHaveBeenLastCalledWith(expect.objectContaining({ baseUrl: 'https://example.atlassian.net', organizationId: ORG_A }));
    expect(created.apiToken).toBe('[MASKED]');
  });
});
